int32_t compiler__driver__commands__cmd_snap(const char* manifest_path, bool update) {
    config__project__ProjectConfig cfg = (std__io__file_exists(manifest_path) ? config__project__ProjectConfig_new(manifest_path) : (config__project__ProjectConfig){ "kobel", "1.0.0", "src/main.kb", "build/kobel.exe", "cl", "tests" });
    const char* golden_dir = "tests/golden";
    const char* tmp_dir = "build/snap";
    compiler__driver__commands__ensure_dir(golden_dir);
    compiler__driver__commands__ensure_dir(tmp_dir);
    std__collections__list__List_str corpus = compiler__driver__commands__snap_corpus(cfg.test_dir);
    std__io__println("============================================================");
    if (update) {
        std__io__println(kobel_concat(kobel_concat("  Updating C snapshots (", usz_to_str(corpus.len)), " sources)"));
    } else {
        std__io__println(kobel_concat(kobel_concat("  Checking C snapshots (", usz_to_str(corpus.len)), " sources)"));
    }
    std__io__println("============================================================");
    int32_t fail_count = 0;
    {
        size_t __for_n = std__collections__list__List_str_count(&corpus);
        size_t __for_i = 0;
        while (__for_i < __for_n) {
            const char* src = std__collections__list__List_str_at(&corpus, __for_i);
            std__io__print(kobel_concat(kobel_concat("[*] ", src), " ... "));
            const char* flat = compiler__driver__commands__snap_name(src);
            const char* c_path = kobel_concat(kobel_concat(kobel_concat(tmp_dir, "/"), flat), ".c");
            compiler__driver__pipeline__CompileOptions opts = (compiler__driver__pipeline__CompileOptions){ "", "", "", "cl", false, std__collections__list__List_str_new(4), false };
            opts.input_path = src;
            opts.emit_c_path = c_path;
            opts.only_emit_c = true;
            opts.quiet = true;
            if (compiler__driver__pipeline__CompileOptions_compile(&opts) != 0) {
                std__io__println("FAIL (emit-c error)");
                fail_count++;
                {
                    __for_i = (__for_i + 1);
                    continue;
                }
            }
            const char* digest = str_hash_stamp(std__io__read_file(c_path));
            const char* golden_path = kobel_concat(kobel_concat(kobel_concat(golden_dir, "/"), flat), ".txt");
            if (update) {
                std__io__write_file(golden_path, kobel_concat(digest, "\n"));
                std__io__println("UPDATED");
                {
                    __for_i = (__for_i + 1);
                    continue;
                }
            }
            if (!std__io__file_exists(golden_path)) {
                std__io__println("FAIL (missing golden; run 'kobel snap --update')");
                fail_count++;
                {
                    __for_i = (__for_i + 1);
                    continue;
                }
            }
            const char* expected = str_trim(std__io__read_file(golden_path));
            if (kobel_streq(expected, digest)) {
                std__io__println("PASS");
            } else {
                std__io__println("FAIL");
                std__io__println(kobel_concat("    expected ", expected));
                std__io__println(kobel_concat("    actual   ", digest));
                fail_count++;
            }
            __for_i = (__for_i + 1);
        }
    }
    std__io__println("------------------------------------------------------------");
    if (fail_count > 0) {
        std__io__println(kobel_concat(kobel_concat("[ERROR] ", i32_to_str(fail_count)), " snapshot(s) changed. If the change is intended, run 'kobel snap --update' and commit tests/golden."));
        return 1;
    }
    std__io__println(kobel_concat(kobel_concat("[SUCCESS] All ", usz_to_str(corpus.len)), " snapshots match."));
    return 0;
}

int32_t compiler__driver__commands__cmd_fixpoint(const char* manifest_path) {
    config__project__ProjectConfig cfg = (std__io__file_exists(manifest_path) ? config__project__ProjectConfig_new(manifest_path) : (config__project__ProjectConfig){ "kobel", "1.0.0", "src/main.kb", "build/kobel.exe", "cl", "tests" });
    const char* dir = "build/fixpoint";
    compiler__driver__commands__ensure_dir(dir);
    const char* stage1_c = kobel_concat(dir, "/stage1.c");
    const char* stage2_c = kobel_concat(dir, "/stage2.c");
    const char* stage2_exe = kobel_concat(dir, "/kobel_v2.exe");
    const char* stage2_obj = kobel_concat(dir, "/kobel_v2.obj");
    std__io__println("[1/3] Emitting C from the current compiler...");
    compiler__driver__pipeline__CompileOptions opts = (compiler__driver__pipeline__CompileOptions){ "", "", "", "cl", false, std__collections__list__List_str_new(4), false };
    opts.input_path = cfg.entry;
    opts.emit_c_path = stage1_c;
    opts.only_emit_c = true;
    opts.quiet = true;
    if (compiler__driver__pipeline__CompileOptions_compile(&opts) != 0) {
        std__io__println(kobel_concat(kobel_concat("[ERROR] Could not emit C for '", cfg.entry), "'."));
        return 1;
    }
    std__io__println("[2/3] Building the second-generation compiler...");
    std__sys__exec(compiler__driver__pipeline__c_compile_cmd(stage1_c, stage2_exe, stage2_obj, cfg.cc, true));
    if (!std__io__file_exists(stage2_exe)) {
        std__io__println(kobel_concat(kobel_concat("[ERROR] Backend compiler did not produce '", stage2_exe), "'."));
        return 1;
    }
    std__io__println("[3/3] Re-emitting C with the second-generation compiler...");
    const char* run_exe = str_to_win_path(stage2_exe);
    if (str_contains(run_exe, " ")) {
        run_exe = kobel_concat(kobel_concat("\"", run_exe), "\"");
    }
    int32_t exit_code = std__sys__exec(kobel_concat(kobel_concat(kobel_concat(kobel_concat(run_exe, " "), cfg.entry), " -emit-c "), stage2_c));
    if (exit_code != 0) {
        std__io__println(kobel_concat(kobel_concat("[ERROR] Second-generation compiler failed (exit ", i32_to_str(exit_code)), ")."));
        return 1;
    }
    const char* first = std__io__read_file(stage1_c);
    const char* second = std__io__read_file(stage2_c);
    if (kobel_streq(first, second)) {
        std__io__println(kobel_concat(kobel_concat("[SUCCESS] Fixpoint reached: stage1.c == stage2.c (", usz_to_str(kobel_slen(first))), " bytes)."));
        return 0;
    }
    std__io__println(kobel_concat(kobel_concat(kobel_concat(kobel_concat("[ERROR] Fixpoint broken: stage1.c (", usz_to_str(kobel_slen(first))), " bytes) != stage2.c ("), usz_to_str(kobel_slen(second))), " bytes)."));
    std__collections__list__List_str a_lines = str_split_lines(first);
    std__collections__list__List_str b_lines = str_split_lines(second);
    size_t i = 0;
    while (((i < a_lines.len) && (i < b_lines.len)) && kobel_streq(std__collections__list__List_str_get(&a_lines, i), std__collections__list__List_str_get(&b_lines, i))) {
        i++;
    }
    std__io__println(kobel_concat(kobel_concat("  First difference at line ", usz_to_str((i + 1))), ":"));
    if (i < a_lines.len) {
        std__io__println(kobel_concat("    stage1: ", std__collections__list__List_str_get(&a_lines, i)));
    }
    if (i < b_lines.len) {
        std__io__println(kobel_concat("    stage2: ", std__collections__list__List_str_get(&b_lines, i)));
    }
    return 1;
}

